import React, { useState, useEffect } from "react";
import PageWrapper from "../components/PageWrapper";
import BookCard from "../components/BookCard";
import BookGrid from "../components/BookGrid";
import CardButton from "../components/CardButton";
import styled from "styled-components";
import withLoadingAnimation from "../components/withLoadingAnimation"; // <--- import HOC

const PaginationWrapper = styled.div`
  display: flex;
  justify-content: center;
  margin-top: 24px;
`;

const Button = styled.button`
  padding: 8px 14px;
  background-color: #3498db;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 15px;
  margin: 0 4px;

  &:hover {
    background-color: #2980b9;
  }

  &:disabled {
    opacity: 0.5;
    cursor: default;
  }
`;

const RemoveWrapper = styled.div`
  margin-top: 8px;
  display: flex;
  justify-content: center;
`;

const MyBooks = () => {
    const [books, setBooks] = useState({});
    const [page, setPage] = useState(1);
    const [loading, setLoading] = useState(true);

    const bookList = Object.values(books);
    const pageSize = 15;
    const totalPages = Math.ceil(bookList.length / pageSize);

    // Simulate loading from localStorage
    useEffect(() => {
        setLoading(true);
        const storedBooks = JSON.parse(localStorage.getItem("books")) || {};
        setTimeout(() => {
            setBooks(storedBooks);
            setLoading(false);
        }, 800); // small delay to show animation
    }, []);

    const removeLib = (title) => {
        const updatedBooks = { ...books };
        delete updatedBooks[title];
        setBooks(updatedBooks);
        localStorage.setItem("books", JSON.stringify(updatedBooks));
    };

    // Wrap BookCard with loading HOC
    const BookCardWithLoading = withLoadingAnimation(BookCard);

    return (
        <PageWrapper>
            <h2>My Book Library</h2>

            {bookList.length === 0 && !loading ? (
                <p>No books in your library. Please add some!</p>
            ) : (
                <>
                    <BookGrid>
                        {bookList
                            .slice((page - 1) * pageSize, page * pageSize)
                            .map((book) => (
                                <div key={book.isbn}>
                                    <BookCardWithLoading loading={loading} {...book} />
                                    <RemoveWrapper>
                                        <CardButton
                                            variant="remove"
                                            onClick={() => removeLib(book.title)}
                                        >
                                            Remove
                                        </CardButton>
                                    </RemoveWrapper>
                                </div>
                            ))}
                    </BookGrid>

                    {totalPages > 1 && (
                        <PaginationWrapper>
                            {page > 1 && <Button onClick={() => setPage(page - 1)}>{"<"}</Button>}

                            {Array.from({ length: totalPages }, (_, i) => (
                                <Button
                                    key={i}
                                    onClick={() => setPage(i + 1)}
                                    disabled={page === i + 1}
                                >
                                    {i + 1}
                                </Button>
                            ))}

                            {page < totalPages && <Button onClick={() => setPage(page + 1)}>{">"}</Button>}
                        </PaginationWrapper>
                    )}
                </>
            )}
        </PageWrapper>
    );
};

export default MyBooks;
